import {dismissOpeningIntro} from './helpers/opening.mjs';
import {referenceRendererOptions} from './helpers/reference-renderer.mjs';
import test from 'node:test';
import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {readFile,mkdir,writeFile} from 'node:fs/promises';
import {fileURLToPath} from 'node:url';
import {chromium} from '@playwright/test';
const {version}=JSON.parse(await readFile(new URL('../dist/release.json',import.meta.url),'utf8'));
const port=4185,base='http://127.0.0.1:'+port;
let server,browser;
test.before(async()=>{
 server=spawn(process.execPath,['server.mjs'],{env:{...process.env,PORT:String(port),COACH_ENABLED:'false'},stdio:'pipe'});
 await new Promise((resolve,reject)=>{server.stdout.once('data',resolve);server.once('error',reject);server.once('exit',code=>reject(Error('Server exited '+code)));});
 browser=await chromium.launch({headless:true,...referenceRendererOptions()});
});
test.after(async()=>{await browser?.close();server?.kill();});
async function open(t,viewport={width:1440,height:1000}){
 const context=await browser.newContext({viewport}),page=await context.newPage(),errors=[];page.setDefaultTimeout(10000);
 page.on('pageerror',e=>errors.push(e.message));
 t.after(async()=>{const dir=new URL('../work/qa/',import.meta.url),name=t.name.replace(/[^a-z0-9]+/gi,'-');await mkdir(dir,{recursive:true});try{await page.screenshot({path:fileURLToPath(new URL(name+'.png',dir)),fullPage:true});await writeFile(new URL(name+'.json',dir),JSON.stringify({errors,text:await page.locator('body').innerText()},null,2));}finally{await context.close();}assert.deepEqual(errors,[]);});
 await page.goto(base+'/?qa=1');await dismissOpeningIntro(page);await page.locator(`body[data-build="${version}"]`).waitFor();return page;
}
