const europeSave=page=>page.evaluate(async()=>{await (await import('/mode-storage.js')).flushModeStorage();return (await import('/large-save.js')).readMode('touchline.europe.qa.v1');});

async function openMatchPanels(page){await page.locator('.live-fixture').waitFor();await page.locator('.live-fixture details.live-settings,.live-fixture details.live-match-detail,.live-fixture details.live-match-coach,.live-fixture details.live-match-tactics').evaluateAll(nodes=>nodes.forEach(n=>n.open=true));}
async function goTactics(page){await page.getByRole('button',{name:'Squad',exact:true}).click();await page.locator('[data-action=eu-view-squad-tab][data-value=tactics]').click();}
async function startManaged(page){await page.getByRole('button',{name:'Office',exact:true}).click();const resume=page.getByRole('button',{name:'Resume match',exact:true});if(await resume.count())await resume.click();else{await page.getByRole('button',{name:'Prepare next match',exact:true}).click();await page.getByRole('button',{name:'Manage next fixture',exact:true}).click();}await openMatchPanels(page);}
async function fastManager(page){await page.getByRole('button',{name:'Office',exact:true}).click();await page.getByRole('button',{name:'Prepare next match',exact:true}).click();await page.getByRole('button',{name:'Simulate next matchday',exact:true}).click();}
async function advanceManager(page){await page.getByRole('button',{name:'Season',exact:true}).click();await page.getByText('Season advancement & records',{exact:true}).click();await page.getByRole('button',{name:'Advance until a decision',exact:true}).click();}
async function nextManagerSeason(page){await page.getByRole('button',{name:'Season',exact:true}).click();await page.getByRole('tab',{name:'Season reviews',exact:true}).click();await page.getByRole('button',{name:'Start next season',exact:true}).click();}
async function finishFounderSetup(page){while(await page.getByRole('button',{name:'Continue setup',exact:true}).count())await page.getByRole('button',{name:'Continue setup',exact:true}).click();await page.getByRole('button',{name:'Create club & start career',exact:true}).click();}

async function waitIdle(page){await page.locator('.matchday-busy').waitFor({state:'hidden'});}
async function startManager(page){await page.getByRole('button',{name:'Managerial mode',exact:true}).click();await page.getByRole('button',{name:'Open Club manager career',exact:true}).click();await page.getByRole('button',{name:'Historic & fantasy',exact:true}).click();await page.getByRole('button',{name:'Start club career',exact:true}).click();}
async function historicEurope(page,pack=null){await page.getByRole('button',{name:'Draft & Europe',exact:true}).click();if(pack)await page.locator('#ucl-pack').selectOption(pack);await page.getByRole('button',{name:'Use this historic squad',exact:true}).click();await page.locator('[data-action="eu-manager"]').first().click();}

test('local HTTP serves the app and assets and keeps inference disabled',async()=>{
 for(const path of ['/','/app.js','/vendor/three.module.js','/assets/athlete/characterMedium.fbx','/assets/athlete/idle.fbx','/assets/athlete/run.fbx']){
  const response=await fetch(base+path);assert.equal(response.status,200,path);assert.ok((await response.arrayBuffer()).byteLength>0);
 }
 const get=await fetch(base+'/api/coach');assert.equal(get.status,405);
 const post=await fetch(base+'/api/coach',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});assert.equal(post.status,503);assert.match((await post.json()).reason,/not enabled/);
 const oversized=await fetch(base+'/api/coach',{method:'POST',body:'x'.repeat(16001)});assert.equal(oversized.status,413);
 assert.equal((await fetch(base+'/missing-file.js')).status,404);
});

