test('connected manager saves live play, reproduces its replay, and completes two three-competition seasons',{timeout:180000},async t=>{
 const page=await open(t);await startManager(page);await startManaged(page);await page.locator('[data-live="preset"][data-value="press"]').click();await page.locator('#fixture-build').selectOption('short');
 await page.locator('[data-live="play"]').last().click();await page.locator('[data-live="speed"]').click();await page.locator('[data-live="speed"]').click();await page.waitForFunction(()=>Number(document.querySelector('#fixture-time')?.textContent.match(/^\d+/)?.[0])>=3);
 await page.locator('[data-live="close"]').first().click();const pending=(await europeSave(page)).pending;assert.ok(pending.state.state.world.ticks>0);assert.equal(pending.state.state.buildUps[0],'short');
 await page.reload();await startManaged(page);assert.equal(await page.locator('#fixture-build').inputValue(),'short');await page.locator('[data-live="finish"]').click();await page.locator('#fixture-time').filter({hasText:'FULL-TIME'}).waitFor();const score=await page.locator('#fixture-score').innerText(),stats=await page.locator('#fixture-pulse').textContent();await page.locator('[data-live="close"]').first().click();
 let c=(await europeSave(page)).career;assert.equal(c.history.length,1);assert.equal(c.connected.calendar.fixtures.filter(f=>f.result?.definition).length,1);
 await page.getByRole('button',{name:'Season',exact:true}).click();await page.locator('[data-action="eu-connected-replay"]').first().click();await page.locator('[data-live="finish"]').click();await page.locator('#fixture-time').filter({hasText:'FULL-TIME'}).waitFor();assert.equal(await page.locator('#fixture-score').innerText(),score);assert.equal(await page.locator('#fixture-pulse').textContent(),stats);await page.locator('[data-live="close"]').first().click();
 for(let season=1;season<=2;season++){
  await advanceManager(page);await waitIdle(page);c=(await europeSave(page)).career;assert.equal(c.connected.completed,true);assert.equal(c.competition.results.length,380);assert.equal(c.connected.cup.results.length,19);assert.equal(c.connected.europe.results.length,189);assert.ok(c.management.archive.find(a=>a.season===season)?.connectedReview);await page.reload();
  if(season===1){await nextManagerSeason(page);c=(await europeSave(page)).career;assert.equal(c.season,2);assert.equal(c.history.length,0);}
 }
 assert.ok(c.management.archive.find(a=>a.season===1).physicalResults.length===1);
});

test('save export, import, invalid-file recovery and QA isolation work through settings',{timeout:60000},async t=>{
 const page=await open(t);await startManager(page);await page.getByRole('button',{name:'Settings & saves',exact:true}).click();const downloadPromise=page.waitForEvent('download');await page.getByRole('button',{name:'Export all saves',exact:true}).click();const download=await downloadPromise;const archive=JSON.parse(await readFile(await download.path(),'utf8'));assert.equal(archive.format,'touchline-save');assert.ok(archive.saves[1].career.connected);assert.equal(archive.saves.length,4);
 const before=await europeSave(page);await page.locator('#save-file').setInputFiles({name:'invalid.json',mimeType:'application/json',buffer:Buffer.from('{"format":"invalid"}')});await page.locator('#toast').filter({hasText:'supported Touchline save archive'}).waitFor();assert.deepEqual(await europeSave(page),before);
 page.once('dialog',dialog=>dialog.accept());await page.locator('#save-file').setInputFiles({name:'saves.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(archive))});await page.locator(`body[data-build="${version}"]`).waitFor();await page.waitForFunction(()=>!document.querySelector('#save-file'));assert.deepEqual((await europeSave(page)).career,before.career);
 const normal=await page.evaluate(()=>['touchline.v1','touchline.europe.v1','touchline.practice.v2','touchline.players.v1'].map(k=>localStorage.getItem(k)));assert.deepEqual(normal,[null,null,null,null]);await page.getByRole('button',{name:'Settings & saves',exact:true}).click();const recoveryPromise=page.waitForEvent('download');await page.getByRole('button',{name:'Download recovery copy',exact:true}).click();const recovery=await recoveryPromise;assert.equal(JSON.parse(await readFile(await recovery.path(),'utf8')).format,'touchline-save');
});

