test('Quick Match pauses, substitutes, reloads its commands and finishes in isolation',{timeout:60000},async t=>{
 const page=await open(t);await page.getByRole('button',{name:'Match centre',exact:true}).click();await page.getByText('Original practice matches & saved replays',{exact:true}).click();await page.getByRole('button',{name:'Open original practice match',exact:true}).click();await page.getByRole('button',{name:'Take the touchline',exact:true}).click();await page.getByRole('button',{name:'Change playback speed',exact:true}).click();await page.getByRole('button',{name:'Change playback speed',exact:true}).click();await page.waitForFunction(()=>Number(document.querySelector('#minute-progress')?.textContent.split('/')[0])>=3);await page.locator('[data-action="play"]').first().click();
 const getMatch=()=>page.evaluate(()=>JSON.parse(localStorage.getItem('touchline.qa.v2')).match);const paused=await getMatch();assert.ok(paused.state.minute>=3);await page.getByRole('button',{name:'Bench',exact:true}).click();await page.locator('[data-action="sub"]').first().click();let match=await getMatch();assert.equal(match.state.subs,1);const commands=match.state.actions;await page.reload();match=await getMatch();assert.deepEqual(match.state.actions,commands);assert.equal(match.state.world.ticks,paused.state.world.ticks);await page.getByRole('button',{name:'Full-time',exact:true}).click();match=await getMatch();assert.equal(match.state.finished,true);assert.equal(match.state.minute,90);await page.reload();assert.deepEqual((await getMatch()).state.score,match.state.score);assert.equal(await page.evaluate(()=>localStorage.getItem('touchline.v1')),null);
});

