test('repeated fixture opening releases every WebGL context and loads all local assets',{timeout:90000},async t=>{
 const page=await open(t),failures=[];page.on('response',r=>{if(r.url().includes('/assets/')&&r.status()>=400)failures.push(r.url());});await page.evaluate(()=>{window.viewLifecycle={created:0,lost:0};const get=HTMLCanvasElement.prototype.getContext,seen=new WeakSet();HTMLCanvasElement.prototype.getContext=function(type,...args){const result=get.call(this,type,...args);if(type.startsWith('webgl')&&result&&!seen.has(this)){seen.add(this);window.viewLifecycle.created++;this.addEventListener('webglcontextlost',()=>window.viewLifecycle.lost++);}return result;};});await startManager(page);
 for(let i=0;i<6;i++){await startManaged(page);await page.waitForFunction(()=>document.querySelector('.live-fixture canvas')?.dataset.athletes);assert.equal(await page.locator('.live-fixture canvas').getAttribute('data-asset-error'),null);await page.locator('[data-live=close]').first().click();await page.waitForFunction(()=>window.viewLifecycle.created===window.viewLifecycle.lost);assert.equal(await page.locator('.live-fixture canvas').count(),0);}
 assert.deepEqual(await page.evaluate(()=>window.viewLifecycle),{created:6,lost:6});assert.deepEqual(failures,[]);
});

