d(page);await page.waitForFunction(()=>document.querySelector('.live-fixture canvas')?.dataset.athletes);await page.locator('[data-live=close]').first().click();assert.equal((await europeSave(page)).career.credits,c.credits);await page.getByRole('button',{name:'Club',exact:true}).click();await page.getByRole('button',{name:'Finances',exact:true}).click();assert.match(await page.locator('.sandbox-finance').innerText(),/Annual committed wages/i);
