test('Super League completes two seasons with a loan return, physical archive and exact reload recovery',{timeout:180000},async t=>{
 const page=await open(t);await page.getByRole('button',{name:'Create a club',exact:true}).click();await page.getByLabel('Club name',{exact:true}).fill('Two Season Borough');await page.getByRole('button',{name:'Continue setup',exact:true}).click();await page.getByLabel('Career competition',{exact:true}).selectOption('super-league');await finishFounderSetup(page);const loan=await page.evaluate(async()=>{const {sandboxMarket,worldPlayer,legalClub}=await import('/sandbox-world.js');const c=JSON.parse(localStorage.getItem('touchline.europe.qa.v1')).career,p=sandboxMarket(c).find(p=>p.role==='MID'&&p.rating<85&&worldPlayer(c,p.id).contractEnd>='2027-06-30'&&legalClub(c,p.worldRegistration,worldPlayer(c,p.id).id));return {id:p.id,name:p.name,parent:p.worldOwner};});await page.getByRole('button',{name:'Transfers',exact:true}).click();await page.getByLabel('Player name',{exact:true}).fill(loan.name);await page.getByRole('button',{name:'Search players',exact:true}).click();await page.getByRole('button',{name:'Enquire for loan',exact:true}).click();await page.locator('[data-manager-form=deal] [name=role]').selectOption('rotation');await page.locator('[data-manager-form=deal] button').click();await page.locator('[data-manager-form=deal] button').click();await page.getByRole('button',{name:'Confirm agreement',exact:true}).click();assert.equal((await europeSave(page)).career.management.deals.at(-1).stage,'complete');await startManaged(page);await page.waitForFunction(()=>document.querySelector('.live-fixture canvas')?.dataset.athletes);await page.locator('[data-live=close]').first().click();await page.reload();await startManaged(page);await page.getByRole('button',{name:'Simulate to full-time',exact:true}).click();await page.getByText('FULL-TIME',{exact:true}).waitFor({timeout:15000});await page.getByRole('button',{name:'Return to competition',exact:true}).first().click();await waitIdle(page);
 for(let season=1;season<=2;season++){let guard=0;while(!(await europeSave(page)).career.competition.champion&&guard++<10){await advanceManager(page);await waitIdle(page);const c=(await europeSave(page)).career;if(c.management.inbox.some(x=>!x.resolved&&x.mandatory)){await page.getByRole('button',{name:'Office',exact:true}).click();while(await page.locator('[data-action=eu-view-message]').count()){await page.locator('[data-action=eu-view-message]').first().click();await page.getByRole('button',{name:'Agree a rotation role',exact:true}).first().click();}}}
  const c=(await europeSave(page)).career;assert.equal(c.competition.results.length,380);assert.equal(c.history.length,38);assert.equal(c.management.archive.length,season);const snapshot=structuredClone(c);await page.reload();assert.deepEqual((await europeSave(page)).career,snapshot);if(season===1){await nextManagerSeason(page);const next=(await europeSave(page)).career;assert.equal(next.season,2);assert.equal(next.world.players.find(p=>p.profileId===loan.id).registeredClub,loan.parent);assert.equal(next.condition[loan.id],undefined);}}
 const final=(await europeSave(page)).career;assert.equal(final.management.archive[0].physicalResults.length,1);assert.equal(final.world.members.length,20);assert.equal(new Set(final.world.players.map(p=>p.id)).size,final.world.players.length);await page.getByRole('button',{name:'Season',exact:true}).click();await page.getByRole('tab',{name:'Season reviews',exact:true}).click();assert.equal(await page.getByRole('button',{name:/Replay recorded match/}).count(),1);
});




